const d = $json;

const SYSTEM = "You write short, personal 'we miss you' emails for a luxury watch dealer to past customers who have been quiet. Write in the customer's language (ISO code given). Warm, personal, max 130 words. Refer to their past purchase or interests if known (e.g. ask how they enjoy their watch). Suggest the watches given, with price in USD, and offer a private viewing. Never offer discounts. Only use facts given. Plain text, no markdown. End with the business name and 'Reply STOP to unsubscribe.' (translated).";
const SCHEMA = {
  "type": "object",
  "properties": {
    "subject": {
      "type": "string"
    },
    "body": {
      "type": "string"
    }
  },
  "required": [
    "subject",
    "body"
  ],
  "additionalProperties": false
};
const userContent = `Business: ${d.business_name}
Customer name: ${d.name || ''}
Customer language: ${d.language}
Past purchases: ${d.past_purchases || 'none'}
Interests: ${d.interests || 'unknown'}
Watches to suggest (JSON): ${JSON.stringify(d.suggestions || [])}`;

return {
  json: {
    claude_request: {
      model: 'claude-opus-5',
      max_tokens: 16000,
      fallbacks: 'default',              // if the model declines, Anthropic retries on a fallback model
      system: SYSTEM,
      messages: [{ role: 'user', content: userContent }],
      output_config: {
        effort: 'medium',             // low / medium / high: more effort = better answers, more cost
        format: { type: 'json_schema', schema: SCHEMA },
      },
    },
  },
};

// Read Claude's answer. The answer is JSON because we asked for a JSON schema.
const res = $json;
if (res.stop_reason === 'refusal') {
  throw new Error('Claude declined this request: ' + JSON.stringify(res.stop_details || {}));
}
const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
if (!text) {
  throw new Error('Claude returned no text: ' + JSON.stringify(res).slice(0, 500));
}
const ai = JSON.parse(text);

const d = $('Inactive customers').item.json;
return { json: { ...d, subject: ai.subject, body: ai.body } };

// When the database query finds nothing, n8n still passes one item: {"success": true}.
// Remove it so the next steps only run for real rows.
return $input.all()
  .map((item, index) => ({ json: item.json, pairedItem: { item: index } }))
  .filter(item => !(Object.keys(item.json).length === 1 && item.json.success === true));
